interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type OrderEvent = {
  type: "order";
  id: unknown;
  item: unknown;
  qty: unknown;
};
type CancelEvent = { type: "cancel"; id: unknown };
type ShipEvent = { type: "ship"; id: unknown; qty?: unknown };
type RestockEvent = { type: "restock"; item: unknown; qty: unknown };
type ExpireEvent = { type: "expire"; id: unknown };
type AnyEvent = OrderEvent | CancelEvent | ShipEvent | RestockEvent | ExpireEvent;

/**
 * Stock on hand for an item, treating missing entries as zero.
 */
function stockOnHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/**
 * A non-empty id field.
 */
function hasId(event: Record<string, unknown>): boolean {
  return typeof event.id === "string" && event.id.length > 0;
}

/**
 * A non-empty item field.
 */
function hasItem(event: Record<string, unknown>): boolean {
  return typeof event.item === "string" && event.item.length > 0;
}

/**
 * A quantity that is a positive (>= 1) integer.
 */
function isValidQty(qty: unknown): boolean {
  return typeof qty === "number" && Number.isInteger(qty) && qty >= 1;
}

/**
 * Deduct stock to fulfill as many queued (backordered) wants as possible,
 * in FIFO order, promoting them to reserved. Mutates the shared state.
 */
function fulfillQueue(
  stock: Record<string, number>,
  queue: string[],
  pendingWants: Record<string, Want>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = stockOnHand(stock, want.item);
    if (onHand < want.qty) {
      continue;
    }
    stock[want.item] = onHand - want.qty;
    reserved[pendingId] = { item: want.item, qty: want.qty };
    orders[pendingId] = "reserved";
    delete pendingWants[pendingId];
    queue.splice(position, 1);
    position = position - 1; // same index now holds the next queued want
  }
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as AnyEvent;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    switch (event.type) {
      case "order": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (orders[event.id] !== undefined) {
          return { ok: false, error: "event " + index + ": duplicate order" };
        }
        if (!hasItem(event) || typeof event.item !== "string") {
          return { ok: false, error: "event " + index + ": bad item" };
        }
        if (!isValidQty(event.qty) || typeof event.qty !== "number") {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        const available = stockOnHand(stock, event.item);
        if (available >= event.qty) {
          stock[event.item] = available - event.qty;
          reserved[event.id] = { item: event.item, qty: event.qty };
          orders[event.id] = "reserved";
        } else {
          queue.push(event.id);
          pendingWants[event.id] = { item: event.item, qty: event.qty };
          orders[event.id] = "backordered";
        }
        break;
      }

      case "cancel": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (reserved[event.id] !== undefined) {
          const holding = reserved[event.id];
          stock[holding.item] = stockOnHand(stock, holding.item) + holding.qty;
          delete reserved[event.id];
          orders[event.id] = "cancelled";
          fulfillQueue(stock, queue, pendingWants, reserved, orders);
        } else if (orders[event.id] === "backordered") {
          queue.splice(queue.indexOf(event.id), 1);
          delete pendingWants[event.id];
          orders[event.id] = "cancelled";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "ship": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (event.qty !== undefined && (!isValidQty(event.qty) || typeof event.qty !== "number")) {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        const holding = reserved[event.id];
        if (holding === undefined) {
          rejected = rejected + 1;
        } else if (event.qty === undefined || event.qty === holding.qty) {
          delete reserved[event.id];
          orders[event.id] = "shipped";
        } else if (event.qty < holding.qty) {
          holding.qty = holding.qty - event.qty;
          orders[event.id] = "partial";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "restock": {
        if (!hasItem(event) || typeof event.item !== "string") {
          return { ok: false, error: "event " + index + ": bad item" };
        }
        if (!isValidQty(event.qty) || typeof event.qty !== "number") {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        stock[event.item] = stockOnHand(stock, event.item) + event.qty;
        fulfillQueue(stock, queue, pendingWants, reserved, orders);
        break;
      }

      case "expire": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (reserved[event.id] !== undefined) {
          const holding = reserved[event.id];
          stock[holding.item] = stockOnHand(stock, holding.item) + holding.qty;
          delete reserved[event.id];
          orders[event.id] = "expired";
          fulfillQueue(stock, queue, pendingWants, reserved, orders);
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      default:
        return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

const ITEMS = ["a", "b", "c"];
const IDS = ["o1", "o2", "o3", "o4"];

function rand(n) { return Math.floor(Math.random() * n); }
function pick(arr) { return arr[rand(arr.length)]; }

function genEvent(orders) {
  const t = ["order", "order", "cancel", "ship", "restock", "expire", "bogus"][rand(7)];
  const e = {};
  e.type = t;
  if (t === "order") {
    e.id = pick(IDS);
    e.item = pick(ITEMS);
    e.qty = rand(6) + 1;
    maybeBad(e, ["id", "item", "qty"]);
  } else if (t === "cancel") {
    e.id = pick(IDS);
    maybeBad(e, ["id"]);
  } else if (t === "ship") {
    e.id = pick(IDS);
    if (rand(3) !== 0) e.qty = rand(6) + 1;
    maybeBad(e, ["id", "qty"]);
  } else if (t === "restock") {
    e.item = pick(ITEMS);
    e.qty = rand(6) + 1;
    maybeBad(e, ["item", "qty"]);
  } else if (t === "expire") {
    e.id = pick(IDS);
    maybeBad(e, ["id"]);
  }
  return e;
}

function maybeBad(e, fields) {
  const r = rand(10);
  if (r === 0) e[fields[0]] = "";
  else if (r === 1) e[fields[0]] = 123;
  else if (r === 2) e[fields[0]] = undefined;
  else if (r === 3) e[fields[0]] = null;
}

function genInput() {
  const stock = {};
  for (const it of ITEMS) stock[it] = rand(8);
  const events = [];
  const n = rand(15);
  for (let i = 0; i < n; i++) events.push(genEvent());
  return { stock, events };
}

function normalize(input) {
  // clone to avoid mutation effects
  return JSON.parse(JSON.stringify(input));
}

function load(modulePath) {
  delete require.cache[require.resolve(modulePath)];
  return require(modulePath);
}

const orig = load("./original.cjs");
const mine = load("./process.export.cjs");

let mismatches = 0;
for (let trial = 0; trial < 200000; trial++) {
  const input = genInput();
  const a = orig.processEvents(normalize(input));
  const b = mine.processEvents(normalize(input));
  const sa = JSON.stringify(a);
  const sb = JSON.stringify(b);
  if (sa !== sb) {
    mismatches++;
    if (mismatches <= 5) {
      console.log("MISMATCH", JSON.stringify(input));
      console.log("  orig:", sa);
      console.log("  mine:", sb);
    }
  }
}
console.log("mismatches:", mismatches);

